//! 📥️ Real Chart producers bind the shared closed owners to authored native assets.
use super::{corpus,owned,exact,file,independent};
use crate::ChartSnapshot;
use protocol::{ArtifactDsl,ArtifactPack,ArtifactSqliteSnapshot};
#[test]
fn chart_logical_owner_fixture_producer(){
 let c=corpus();let cases=c["cases"].as_array().unwrap();assert_eq!(cases.len(),4);
 let output=if std::env::var("SEMIO_CHART_FIXTURE_PRODUCE").as_deref()==Ok("1"){let path=std::path::PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").expect("repository-owned artifact output directory")).join("chart-logical-owner");std::fs::create_dir_all(&path).unwrap();Some(path)}else{None};
 for(index,case)in cases.iter().enumerate(){let expected=owned(case);let text=expected.print_dsl();let binary=expected.encode_pack_with(&Default::default()).unwrap();let from_text=ChartSnapshot::parse_dsl(&text).unwrap();let from_binary=ChartSnapshot::decode_pack(&binary).unwrap();exact(&from_text.chart,&expected.chart);exact(&from_binary.chart,&expected.chart);assert_eq!(from_text.print_dsl(),text);assert_eq!(from_binary.encode_pack_with(&Default::default()).unwrap(),binary);let row:serde_json::Value=serde_json::from_slice(&independent(r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');console.log(JSON.stringify(d.query('SELECT width,height,language FROM chart_document').get()));d.close();"#,&file(&from_binary))).unwrap();assert_eq!(row["width"],case["snapshot"]["chart"]["width"]);assert_eq!(row["height"],case["snapshot"]["chart"]["height"]);assert_eq!(row["language"],case["snapshot"]["chart"]["language"]);if let Some(directory)=&output{std::fs::write(directory.join(format!("🗣️{index}.dsl.semio")),text.as_bytes()).unwrap();std::fs::write(directory.join(format!("🎒️{index}.pack.semio")),&binary).unwrap();}}
 eprintln!("[DEBUG] Chart four real Text/Pack producers retained every closed owner and independent SQLite integrity");
}

#[test]
fn sqlite_snapshot_chart_canonical_logical_owner_assets_match_actual_producers(){
 let c=corpus();for(index,(text,binary))in[(include_str!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🗣️0.dsl.semio"),include_bytes!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🎒️0.pack.semio").as_slice()),(include_str!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🗣️1.dsl.semio"),include_bytes!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🎒️1.pack.semio").as_slice()),(include_str!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🗣️2.dsl.semio"),include_bytes!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🎒️2.pack.semio").as_slice()),(include_str!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🗣️3.dsl.semio"),include_bytes!("../../../../../🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧠️logical-owner/🎒️3.pack.semio").as_slice())].into_iter().enumerate(){let expected=owned(&c["cases"][index]);let a=ChartSnapshot::parse_dsl(text).unwrap();let b=ChartSnapshot::decode_pack(binary).unwrap();exact(&a.chart,&expected.chart);exact(&b.chart,&expected.chart);assert_eq!(expected.print_dsl(),text);assert_eq!(expected.encode_pack_with(&Default::default()).unwrap(),binary);for(encoding,payload)in[(protocol::sqlite_snapshot::SnapshotEncoding::Text,protocol::io_schema::IoPayload::Text(text.into())),(protocol::sqlite_snapshot::SnapshotEncoding::Binary,protocol::io_schema::IoPayload::Binary(binary.into()))]{let emitted=expected.encode_sqlite_snapshot_native(encoding,&mut protocol::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(emitted,payload);let length=match &payload{protocol::io_schema::IoPayload::Text(text)=>text.len(),protocol::io_schema::IoPayload::Binary(bytes)=>bytes.len()};let exact_limit=protocol::sqlite_snapshot::SqliteDatabaseLimits{max_file_bytes:length,..Default::default()};expected.preflight_sqlite_snapshot_encoding(encoding,&mut protocol::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,exact_limit)).unwrap();let short_limit=protocol::sqlite_snapshot::SqliteDatabaseLimits{max_file_bytes:length-1,..Default::default()};assert!(expected.preflight_sqlite_snapshot_encoding(encoding,&mut protocol::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,short_limit)).is_err());let actual=ChartSnapshot::decode_sqlite_snapshot_native(&payload,&mut protocol::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();exact(&actual.chart,&expected.chart);}}
 eprintln!("[DEBUG] Chart eight authored assets equal the actual ordinary and controlled Text/Pack producers for all four neutral owners");
}
